out <- file(paste0("b1-", mode, ".txt"), "w")
for (e in exprs) {
  res <- tryCatch({
    ws <- character()
    co <- capture.output(v <- withCallingHandlers(eval(parse(text=e), new.env(parent=globalenv())), warning=function(w){ws <<- c(ws, paste(class(w)[1], conditionMessage(w))); invokeRestart("muffleWarning")}))
    d <- if (is.object(v) && inherits(v, c("zu_int64","integer64"))) paste0("<", paste(class(v), collapse="/"), "> ", paste(tryCatch(zuint:::zu_as_character(int64(v)), error=function(e) "??"), collapse=" "), if (!is.null(names(v))) paste(" nm:", paste(names(v), collapse="|")))
         else paste(capture.output(print(v)), collapse="\n   ")
    paste0(d, if (length(co)) paste0("\n  OUT: ", paste(co, collapse="\n   ")), if (length(ws)) paste0("\n  WARN: ", paste(ws, collapse=" ; ")))
  }, error=function(err) paste("ERROR", class(err)[1], conditionMessage(err)))
  writeLines(c(paste("##", e), paste("  ", res)), out)
}
close(out)
